class Base {
public:
    virtual ~Base() = default;
    virtual void exec() const = 0; // VTable entry 1
};

class Derived : public Base {
    void exec() const override {}
    // Derived object has vptr -> Derived vtable
};

// Slicing avoidance: Store pointers, not objects
using PolyPtr = std::unique_ptr<Base>;
std::vector<PolyPtr> container;

container.push_back(std::make_unique<Derived>());
// Runtime polymorphism: container[0]->exec()
// Uses vptr to access the Derived entry in the vtable.
